input.command:
mkdir -p work/run2 && sed -e '/^begin filter 1/,/^end filter/d' -e 's/^  filter_ids 1$/  filter_type helmholtz
  filter_radius_absolute 0.15
  boundary_sticking_penalty 1.0
  symmetry_plane_location_names ss_sym/' work/run/input_deck.i > work/run2/input_deck.i; sed -i 's|^// added per the frozen specification.|// added per the frozen specification. Filter declared with the study-level keyword form
// (manual Table 2.5.12 equivalence) because the filter-block form did not propagate the
// symmetry-plane sideset into the generated Helmholtz configuration (see work/run/).|' work/run2/input_deck.i; cp -p work/mesh/mesh.exo work/run2/mesh.exo; diff work/run/input_deck.i work/run2/input_deck.i; source /uufs/chpc.utah.edu/common/home/chet/Daisy/Thesis/runs/E3_disparate_storage_example8/automation/environment/load_morphorm_e3.sh >/dev/null 2>&1; cd work/run2 && echo "$(date -u +%FT%TZ) XMLGenerator input_deck.i (cwd work/run2, legacy filter keywords)" >> ../notes.log; XMLGenerator input_deck.i > xmlgenerator_stdout.log 2> xmlgenerator_stderr.log; rc=$?; echo xmlgen_rc=$rc; echo "$(date -u +%FT%TZ) XMLGenerator rc=$rc" >> ../notes.log; grep -i 'filter\|sticking\|symmetry' xmlgenerator_stdout.log; cat xmlgenerator_stderr.log; echo ===== HELMHOLTZ; cat analyze_helmholtz_input_deck.xml; echo ===== DIFF-ANALYZE; diff ../run/analyze_2_input_deck.xml analyze_2_input_deck.xml && echo analyze_identical; diff ../run/interface.xml interface.xml && echo interface_identical; diff ../run/engine_operations.xml engine_operations.xml && echo engine_ops_identical; diff ../run/mpirun.source mpirun.source && echo mpirun_identical

mkdir -p work/mesh && cat > work/mesh/mesh.jou <<'EOF'
## E3-SPC-v1 Symmetry-Plane Cantilever: half of the 2 x 1 x 1 cantilever, z in [0, 0.5].
## Structured HEX8 mesh, h = 1/24 (48 x 24 x 12 = 13,824 elements, 15,925 nodes).
## block_1: whole domain; ns_fix: face x = 0; ns_load: edge x = 2, y = 0; ss_sym: faces on z = 0.5.
## Constructed for trial E3-clio-trial_07 from the frozen specification; the structured-brick
## meshing pattern follows candidate example_07 (full-domain journal), adapted to the half width.
reset
#{len = 2.0}
#{ht  = 1.0}
#{wd  = 0.5}
#{esize = 0.0416667}
## --- geometry: half brick with the corner at the origin ---
create brick x {len} y {ht} z {wd}
move volume 1 x {len/2.0} y {ht/2.0} z {wd/2.0}
## --- structured hex mesh (48 x 24 x 12) ---
volume 1 scheme map
volume 1 size {esize}
mesh volume 1
block 1 volume 1
block 1 name 'block_1'
block 1 element type HEX8
## --- fixed support: the x = 0 face (all displacements) ---
nodeset 1 add node in surface with x_coord < {esize/2.0}
nodeset 1 name "ns_fix"
## --- transverse line load: bottom-right edge (x = len, y = 0), spanning z in [0, wd] ---
nodeset 2 add node with x_coord > {len - esize/2.0} and with y_coord < {esize/2.0}
nodeset 2 name "ns_load"
## --- symmetry (cut) plane z = wd: all element faces on that surface ---
sideset 1 add surface with z_coord > {wd - esize/2.0}
sideset 1 name "ss_sym"
export mesh "mesh.exo" dimension 3 overwrite
EOF
source /uufs/chpc.utah.edu/common/home/chet/Daisy/Thesis/runs/E3_disparate_storage_example8/automation/environment/load_morphorm_e3.sh >/dev/null 2>&1; cd work/mesh && echo "$(date -u +%FT%TZ) cubit -batch -nographics -nojournal -input mesh.jou (cwd work/mesh)" >> ../notes.log; cubit -batch -nographics -nojournal -input mesh.jou > cubit_stdout.log 2> cubit_stderr.log; echo cubit_rc=$?; echo "$(date -u +%FT%TZ) cubit rc=$? " >> ../notes.log; ls -l; grep -i -n 'error\|warning' cubit_stdout.log | head; tail -15 cubit_stdout.log
